212	// World-space corners, ordered top-left, bottom-left, bottom-right, top-right
213	// as seen from outside the face. Returns corners plus UV corner flags.
214	function faceCorners(dir, from, to) {
215	  const [x1, y1, z1] = from, [x2, y2, z2] = to;
216	  switch (dir) {
217	    case 'south': return [[x1, y2, z2], [x1, y1, z2], [x2, y1, z2], [x2, y2, z2]];
218	    case 'north': return [[x2, y2, z1], [x2, y1, z1], [x1, y1, z1], [x1, y2, z1]];
219	    case 'east': return [[x2, y2, z2], [x2, y1, z2], [x2, y1, z1], [x2, y2, z1]];
220	    case 'west': return [[x1, y2, z1], [x1, y1, z1], [x1, y1, z2], [x1, y2, z2]];
221	    case 'up': return [[x1, y2, z1], [x1, y2, z2], [x2, y2, z2], [x2, y2, z1]];
222	    case 'down': return [[x1, y1, z2], [x1, y1, z1], [x2, y1, z1], [x2, y1, z2]];
223	  }
224	  throw new Error('bad dir ' + dir);
225	}
