3	import com.mojang.math.MatrixUtil;
4	import net.minecraft.core.Direction;
5	import org.joml.Math;
6	import org.joml.Matrix4f;
7	import org.joml.Matrix4fc;
8	import org.joml.Vector3f;
9	import org.joml.Vector3fc;
10	
11	public record CuboidRotation(Vector3fc origin, CuboidRotation.RotationValue value, boolean rescale, Matrix4fc transform) {
12	   public CuboidRotation(final Vector3fc origin, final CuboidRotation.RotationValue value, final boolean rescale) {
13	      this(origin, value, rescale, computeTransform(value, rescale));
14	   }
15	
16	   private static Matrix4f computeTransform(final CuboidRotation.RotationValue value, final boolean rescale) {
17	      Matrix4f result = value.transformation();
18	      if (rescale && !MatrixUtil.isIdentity(result)) {
19	         Vector3fc scale = computeRescale(result);
20	         result.scale(scale);
21	      }
22	
23	      return result;
24	   }
25	
26	   private static Vector3fc computeRescale(final Matrix4fc rotation) {
27	      Vector3f scratch = new Vector3f();
28	      float scaleX = scaleFactorForAxis(rotation, Direction.Axis.X, scratch);
29	      float scaleY = scaleFactorForAxis(rotation, Direction.Axis.Y, scratch);
30	      float scaleZ = scaleFactorForAxis(rotation, Direction.Axis.Z, scratch);
31	      return scratch.set(scaleX, scaleY, scaleZ);
32	   }
33	
34	   private static float scaleFactorForAxis(final Matrix4fc rotation, final Direction.Axis axis, final Vector3f scratch) {
35	      Vector3f axisUnit = scratch.set(axis.getPositive().getUnitVec3f());
36	      Vector3f transformedAxisUnit = rotation.transformDirection(axisUnit);
37	      float absX = Math.abs(transformedAxisUnit.x);
38	      float absY = Math.abs(transformedAxisUnit.y);
39	      float absZ = Math.abs(transformedAxisUnit.z);
40	      float maxComponent = Math.max(Math.max(absX, absY), absZ);
41	      return 1.0F / maxComponent;
42	   }
43	
44	   public record EulerXYZRotation(float x, float y, float z) implements CuboidRotation.RotationValue {
45	      @Override
46	      public Matrix4f transformation() {
47	         return new Matrix4f()
48	            .rotationZYX(
49	               this.z * (float) (java.lang.Math.PI / 180.0), this.y * (float) (java.lang.Math.PI / 180.0), this.x * (float) (java.lang.Math.PI / 180.0)
50	            );
51	      }
52	   }
53	
54	   public interface RotationValue {
55	      Matrix4f transformation();
56	   }
57	
58	   public record SingleAxisRotation(Direction.Axis axis, float angle) implements CuboidRotation.RotationValue {
59	      @Override
60	      public Matrix4f transformation() {
61	         Matrix4f result = new Matrix4f();
62	         if (this.angle == 0.0F) {
63	            return result;
64	         } else {
65	            Vector3fc rotateAround = this.axis.getPositive().getUnitVec3f();
66	            result.rotation(this.angle * (float) (java.lang.Math.PI / 180.0), rotateAround);
67	            return result;
68	         }
69	      }
70	   }
71	}
