45	   public static TextureSlots.Data parseTextureMap(final JsonObject texturesObject) {
46	      TextureSlots.Data.Builder builder = new TextureSlots.Data.Builder();
47	
48	      for (Entry<String, JsonElement> entry : texturesObject.entrySet()) {
49	         parseEntry(entry.getKey(), entry.getValue(), builder);
50	      }
