55	   private static void parseEntry(final String slot, final JsonElement value, final TextureSlots.Data.Builder output) {
56	      if (GsonHelper.isStringValue(value) && isTextureReference(value.getAsString())) {
57	         output.addReference(slot, value.getAsString().substring(1));
58	      } else {
59	         output.addTexture(slot, (Material)Material.CODEC.parse(JsonOps.INSTANCE, value).getOrThrow(JsonParseException::new));
60	      }
61	   }
