63	   public record Data(Map<String, TextureSlots.SlotContents> values) {
64	      public static final TextureSlots.Data EMPTY = new TextureSlots.Data(Map.of());
65	
66	      public static class Builder {
67	         private final Map<String, TextureSlots.SlotContents> textureMap = new HashMap<>();
68	
69	         public TextureSlots.Data.Builder addReference(final String slot, final String reference) {
70	            this.textureMap.put(slot, new TextureSlots.Reference(reference));
71	            return this;
72	         }
73	
74	         public TextureSlots.Data.Builder addTexture(final String slot, final Material material) {
75	            this.textureMap.put(slot, new TextureSlots.Value(material));
76	            return this;
77	         }
