85	   private record Reference(String target) implements TextureSlots.SlotContents {
86	   }
87	
88	   public static class Resolver {
89	      private static final Logger LOGGER = LogUtils.getLogger();
90	      private final List<TextureSlots.Data> entries = new ArrayList<>();
91	
92	      public TextureSlots.Resolver addLast(final TextureSlots.Data data) {
93	         this.entries.addLast(data);
94	         return this;
95	      }
96	
97	      public TextureSlots.Resolver addFirst(final TextureSlots.Data data) {
98	         this.entries.addFirst(data);
99	         return this;
100	      }
101	
102	      public TextureSlots resolve(final ModelDebugName debugNameProvider) {
103	         if (this.entries.isEmpty()) {
104	            return TextureSlots.EMPTY;
105	         } else {
106	            Object2ObjectMap<String, Material> resolved = new Object2ObjectArrayMap();
107	            Object2ObjectMap<String, TextureSlots.Reference> unresolved = new Object2ObjectArrayMap();
108	
109	            for (TextureSlots.Data data : Lists.reverse(this.entries)) {
110	               data.values.forEach((slot, contents) -> {
111	                  switch (contents) {
112	                     case TextureSlots.Value value:
113	                        unresolved.remove(slot);
114	                        resolved.put(slot, value.material());
115	                        break;
116	                     case TextureSlots.Reference reference:
117	                        resolved.remove(slot);
118	                        unresolved.put(slot, reference);
119	                        break;
120	                     default:
121	                        throw new MatchException(null, null);
122	                  }
123	               });
124	            }
125	
126	            if (unresolved.isEmpty()) {
127	               return new TextureSlots(resolved);
128	            } else {
