130	
131	               while (hasChanges) {
132	                  hasChanges = false;
133	                  ObjectIterator<it.unimi.dsi.fastutil.objects.Object2ObjectMap.Entry<String, TextureSlots.Reference>> iterator = Object2ObjectMaps.fastIterator(
134	                     unresolved
135	                  );
136	
137	                  while (iterator.hasNext()) {
