139	                     Material maybeResolved = (Material)resolved.get(((TextureSlots.Reference)entry.getValue()).target);
140	                     if (maybeResolved != null) {
141	                        resolved.put((String)entry.getKey(), maybeResolved);
142	                        iterator.remove();
143	                        hasChanges = true;
144	                     }
145	                  }
146	               }
147	
148	               if (!unresolved.isEmpty()) {
