const PERMS = {
  P123: [0, 1, 2], P213: [1, 0, 2], P132: [0, 2, 1],
  P312: [2, 0, 1], P231: [1, 2, 0], P321: [2, 1, 0],
};
const PERM_NAMES = Object.keys(PERMS);

