for (const s of SESSIONS) {
  const subDir = path.join(QODER, 'projects', `C--Users-zht-Documents-Qoder-2026-11-01-${PROJECT_KEY}`, s.id, 'subagents');
  if (!existsSync(subDir)) continue;
  const dir = s.label.startsWith('crashed') ? reportsRoot : path.join(OUT, 'sessions', s.label, 'reports');
  await fs.mkdir(dir, { recursive: true });
  for (const f of (await fs.readdir(subDir)).filter(x => x.endsWith('.jsonl')).sort()) {
    const r = await extractReport(path.join(subDir, f));
    const title = (r.task.split('\n')[0] || '').slice(0, 110);
    const body = [
      `# ${r.id}`,
      '',
      `- 会话：${s.label}`,
      `- 时间：${r.started} → ${r ended || r.started}`.replace(' r ended', ''),
      `- 模型：${r.model || '?'}`,
      `- 转录行数：${r.lines}（助手文本 ${r.allTexts} 条）`,
      `- 工具使用：${r.tools || '—'}`,
      '',
      '## 派发的任务',
      '',
      r.task || '(未记录)',
      '',
      '## 报告（转录末段）',
      '',
      r.report,
      '',
    ].join('\n');
    const safe = title.replace(/[\\/:*?"<>|]/g, '_').slice(0, 70) || r.id.slice(-12);
    const file = `${r.id.slice(-12)}-${safe}.md`;
    await fs.writeFile(path.join(dir, file), body);
